      pushLint('html', sv.html);
      pushLint('css', sv.css);
      pushLint('js', sv.js);
    } catch (_) {}

    const failedTests = [...domResults, ...cssResults].filter(r => !r.passed).concat(lintItems);

    // Optional DOM Snapshot on failure
    if (failedTests.length > 0 || avgVisualScore < (testSpec?.rubric?.visual || 10)) {
