        ${consoleErrors.length > 0 ? `<h3>Console Errors</h3><ul>${consoleErrors.map(e => `<li>${e}</li>`).join('')}</ul>` : ''}
        ${layoutHints.length > 0 ? `<h3>Layout Heuristics</h3><ul>${layoutHints.map(h => `<li style="color: #c2410c;">${h}</li>`).join('')}</ul>` : ''}
