async function executeCssTests(page, cssTestSpec) {
  if (!cssTestSpec || !cssTestSpec.length) return [];

  return page.evaluate((spec) => {
    const normalize = (value) => {
      if (value == null) return '';
      return String(value).trim().toLowerCase();
    };

    const matchesExpected = (actual, test) => {
      const normalizedActual = normalize(actual);

      if (Array.isArray(test.expected)) {
        return test.expected.map((item) => normalize(item)).includes(normalizedActual);
      }

      const matcher = String(test.matcher || test.operator || 'equals').toLowerCase();
      const expected = normalize(test.expected);

      if (matcher === 'includes') {
        return normalizedActual.includes(expected);
      }

      if (matcher === 'notequals') {
        return normalizedActual !== expected;
      }

      return normalizedActual === expected;
    };

    return spec.map(test => {
      let passed = false;
      let hint = test.hint || `Failed CSS test for ${test.selector} { ${test.property}: ${test.expected} }`;
      try {
        if (test.testType === 'ruleExists') {
          const needle = test.selectorContains || test.selector || '';
          passed = false;
          for (const sheet of Array.from(document.styleSheets || [])) {
            let rules;
            try {
              rules = sheet.cssRules || sheet.rules;
            } catch (e) {
              continue; // ignore cross-origin/security errors
            }
            if (!rules) continue;
            for (const rule of Array.from(rules)) {
              if (rule && rule.selectorText && rule.selectorText.includes(needle)) {
                passed = true;
                break;
              }
            }
            if (passed) break;
          }
          if (!passed) hint = test.hint || `Missing CSS rule containing: ${needle}`;
        } else {
          const el = document.querySelector(test.selector);
          if (el) {
            const style = window.getComputedStyle(el, test.pseudo || null);
            const actual = style.getPropertyValue(test.property) || style[test.property];
            passed = matchesExpected(actual, test);
          } else {
            hint = `Element not found: ${test.selector}`;
          }
        }
      } catch (e) {
        hint = `Error parsing CSS properties target`;
      }
      return { 
        testId: test.id || crypto.randomUUID(), 
        passed, 
        hint, 
        selector: test.selector 
      };
    });
  }, cssTestSpec);
}

module.exports = { executeCssTests };

async function executeDomTests(page, domTestSpec) {
  if (!domTestSpec || !domTestSpec.length) return [];

  return page.evaluate((spec) => {
    const normalize = (value) => {
      if (value == null) return '';
      return String(value).trim();
    };

    const needsExpected = new Set([
      'count',
      'textIncludes',
      'textEquals',
      'hasClass',
      'attributeEquals',
      'valueEquals',
      'alertIncludes'
    ]);

    return spec.map(test => {
      let passed = false;
      let hint = test.hint || `Failed DOM test for selector: ${test.selector}`;
      try {
        const assertion = test.assertion || 'exists';
        const expected = normalize(test.expected);

        if (assertion === 'alertCalled') {
          passed = Array.isArray(window.__alerts) && window.__alerts.length > 0;
        } else if (assertion === 'alertIncludes') {
          const alerts = Array.isArray(window.__alerts) ? window.__alerts.map((item) => normalize(item)) : [];
          passed = alerts.some((item) => item.includes(expected));
        } else {
          const elements = document.querySelectorAll(test.selector);
          const element = elements[0];

          if (assertion === 'exists') {
            passed = elements.length > 0;
          } else if (assertion === 'count') {
            passed = elements.length === Number(test.expected);
          } else if (!element) {
            hint = `Element not found: ${test.selector}`;
          } else if (assertion === 'textIncludes') {
            passed = normalize(element.textContent).includes(expected);
          } else if (assertion === 'textEquals') {
            passed = normalize(element.textContent) === expected;
          } else if (assertion === 'hasClass') {
            passed = element.classList.contains(expected);
          } else if (assertion === 'attributeEquals') {
            const attributeName = normalize(test.attribute);
            passed = Boolean(attributeName) && normalize(element.getAttribute(attributeName)) === expected;
            if (!attributeName) hint = 'Attribute name is required for attributeEquals';
          } else if (assertion === 'valueEquals') {
            passed = normalize(element.value) === expected;
          } else {
            hint = test.hint || `Unsupported DOM assertion: ${assertion}`;
          }

          // We clear default hint if we want a specific error
          if (!passed && hint === (test.hint || `Failed DOM test for selector: ${test.selector}`) && needsExpected.has(assertion)) {
            hint = `Expected ${assertion} to match "${expected}" for ${test.selector}`;
          }
        }
      } catch (e) {
        hint = `Invalid selector: ${test.selector}`;
      }
      return { 
        testId: test.id || crypto.randomUUID(), 
        passed, 
        hint, 
        selector: test.selector 
      };
    });
  }, domTestSpec);
}

module.exports = { executeDomTests };

/**
 * Executes interaction steps strictly through Puppeteer layer to mimic real user input.
 */
async function executeInteractions(page, interactionSpec) {
  if (!Array.isArray(interactionSpec) || interactionSpec.length === 0) return;

  const pause = async (delay) => {
    const ms = Number(delay);
    if (!Number.isFinite(ms) || ms <= 0) return;
    await new Promise((resolve) => setTimeout(resolve, ms));
  };

  for (const step of interactionSpec) {
    try {
      const action = String(step?.action || '').trim().toLowerCase();
      const selector = typeof step?.selector === 'string' ? step.selector : '';
      const timeout = Number(step?.timeout) > 0 ? Number(step.timeout) : 2000;

      if (selector && step?.waitForVisible) {
        await page.waitForSelector(selector, { visible: true, timeout });
      } else if (selector && step?.waitForSelector) {
        await page.waitForSelector(selector, { timeout });
      }

      if (action === 'click') {
        await page.click(selector);
      } else if (action === 'hover') {
        await page.hover(selector);
      } else if (action === 'type') {
        const valueToType = String(step?.value || '');
        if (step?.clear) {
          await page.click(selector, { clickCount: 3 });
          await page.keyboard.press('Backspace');
        }
        await page.type(selector, valueToType, { delay: Number(step?.typingDelay) > 0 ? Number(step.typingDelay) : 10 });
      } else if (action === 'scroll') {
        await page.evaluate((s) => {
          const el = document.querySelector(s);
          if (el) el.scrollIntoView({ block: 'center', inline: 'center' });
        }, selector);
      } else if (action === 'keypress') {
        await page.keyboard.press(String(step?.key || 'Enter'));
      } else if (action === 'focus') {
        await page.focus(selector);
      } else if (action === 'select') {
        const values = Array.isArray(step?.value) ? step.value.map((item) => String(item)) : [String(step?.value || '')];
        await page.select(selector, ...values);
      } else if (action === 'check') {
        await page.check(selector);
      } else if (action === 'uncheck') {
        await page.uncheck(selector);
      } else if (action === 'wait') {
        await pause(step?.delay ?? step?.value ?? 150);
      } else if (action === 'waitforselector') {
        await page.waitForSelector(selector, {
          visible: Boolean(step?.waitForVisible),
          timeout
        });
      } else {
        console.warn(`Unsupported interaction action: ${action}`);
        continue;
      }

      if (step?.waitForNavigation) {
        try {
          await page.waitForNavigation({ waitUntil: 'networkidle0', timeout });
        } catch (_) {
          // Some interactions do not navigate; ignore quietly.
        }
      }

      await pause(step?.delay ?? 50);
    } catch (err) {
      console.warn(`Interaction failed for step ${JSON.stringify(step)}:`, err.message);
      // We don't throw here to allow remaining evaluation to proceed,
      // but structural evaluation might fail later due to missed state changes.
    }
  }
}

module.exports = { executeInteractions };

const fs = require('fs');
const { PNG } = require('pngjs');
const pixelmatchImport = require('pixelmatch');

const pixelmatch = pixelmatchImport.default || pixelmatchImport;

function generateVisualDiff(expectedPath, actualPath, diffPath) {
  let img1 = null;
  let img2 = null;
  let diff = null;
  let normalized1 = null;
  let normalized2 = null;

  try {
    img1 = PNG.sync.read(fs.readFileSync(expectedPath));
    img2 = PNG.sync.read(fs.readFileSync(actualPath));

    const width = Math.max(img1.width, img2.width);
    const height = Math.max(img1.height, img2.height);

    normalized1 = new PNG({
      width,
      height,
      colorType: 6,
      inputHasAlpha: true
    });

    normalized2 = new PNG({
      width,
      height,
      colorType: 6,
      inputHasAlpha: true
    });

    normalized1.data.fill(0);
    normalized2.data.fill(0);

    PNG.bitblt(img1, normalized1, 0, 0, img1.width, img1.height, 0, 0);
    PNG.bitblt(img2, normalized2, 0, 0, img2.width, img2.height, 0, 0);

    diff = new PNG({
      width,
      height,
      colorType: 6,
      inputHasAlpha: true
    });

    const numDiffPixels = pixelmatch(
      normalized1.data,
      normalized2.data,
      diff.data,
      width,
      height,
      {
        threshold: 0.1,
        includeAA: false,
        alpha: 0.35,
        diffColor: [255, 0, 0],
        diffColorAlt: [255, 0, 0]
      }
    );

    fs.writeFileSync(diffPath, PNG.sync.write(diff));

    const cellSize = 20;
    const padding = 10;
    const minDiffRatio = 0.02;
    const cellsX = Math.ceil(width / cellSize);
    const cellsY = Math.ceil(height / cellSize);
    const cellCounts = new Uint32Array(cellsX * cellsY);

    for (let y = 0; y < height; y += 1) {
      const rowOffset = y * width * 4;
      const cellY = Math.floor(y / cellSize);

      for (let x = 0; x < width; x += 1) {
        const idx = rowOffset + x * 4;
        const isDiffPixel =
          diff.data[idx] === 255 &&
          diff.data[idx + 1] === 0 &&
          diff.data[idx + 2] === 0 &&
          diff.data[idx + 3] > 0;

        if (!isDiffPixel) {
          continue;
        }

        const cellX = Math.floor(x / cellSize);
        cellCounts[cellY * cellsX + cellX] += 1;
      }
    }

    const mergedHotspots = [];

    const intersectsOrTouches = (boxA, boxB) =>
      boxA.x <= boxB.x + boxB.width &&
      boxA.x + boxA.width >= boxB.x &&
      boxA.y <= boxB.y + boxB.height &&
      boxA.y + boxA.height >= boxB.y;

    const mergeBoxes = (boxA, boxB) => {
      const left = Math.min(boxA.x, boxB.x);
      const top = Math.min(boxA.y, boxB.y);
      const right = Math.max(boxA.x + boxA.width, boxB.x + boxB.width);
      const bottom = Math.max(boxA.y + boxA.height, boxB.y + boxB.height);

      return {
        x: left,
        y: top,
        width: right - left,
        height: bottom - top
      };
    };

    for (let cellY = 0; cellY < cellsY; cellY += 1) {
      for (let cellX = 0; cellX < cellsX; cellX += 1) {
        const cellIndex = cellY * cellsX + cellX;
        const cellOriginX = cellX * cellSize;
        const cellOriginY = cellY * cellSize;
        const cellWidth = Math.min(cellSize, width - cellOriginX);
        const cellHeight = Math.min(cellSize, height - cellOriginY);
        const cellArea = cellWidth * cellHeight;

        if (cellArea <= 0) {
          continue;
        }

        if (cellCounts[cellIndex] < Math.ceil(cellArea * minDiffRatio)) {
          continue;
        }

        let candidate = {
          x: cellOriginX,
          y: cellOriginY,
          width: cellWidth,
          height: cellHeight
        };

        let merged = true;

        while (merged) {
          merged = false;

          for (let i = mergedHotspots.length - 1; i >= 0; i -= 1) {
            if (!intersectsOrTouches(candidate, mergedHotspots[i])) {
              continue;
            }

            candidate = mergeBoxes(candidate, mergedHotspots[i]);
            mergedHotspots.splice(i, 1);
            merged = true;
          }
        }

        mergedHotspots.push(candidate);
      }
    }

    const hotspots = mergedHotspots.map((box) => {
      const x = Math.max(0, box.x - padding);
      const y = Math.max(0, box.y - padding);
      const right = Math.min(width, box.x + box.width + padding);
      const bottom = Math.min(height, box.y + box.height + padding);

      return {
        x,
        y,
        width: Math.max(1, right - x),
        height: Math.max(1, bottom - y)
      };
    });

    return {
      numDiffPixels,
      diffPercentage: (numDiffPixels / (width * height)) * 100,
      hotspots,
      width,
      height
    };
  } finally {
    img1 = null;
    img2 = null;
    diff = null;
    normalized1 = null;
    normalized2 = null;
  }
}

module.exports = { generateVisualDiff };
